	bt2CorderLinksHeap      = 270   // /links: dense link fractal heap
	bt2CorderLinksName      = 416   // /links: name index (type 5)
	bt2CorderLinksCorder    = 454   // /links: creation order index (type 6)
	bt2CorderFilteredOhdr   = 10814 // /filtered: object header
	bt2CorderFilteredIdx    = 11102 // /filtered: chunk index (type 11)
	bt2CorderAttrHeap       = 31620 // /filtered: dense attribute fractal heap
	bt2CorderAttrName       = 31766 // /filtered: attribute name index (type 8)
	bt2CorderAttrCorder     = 31804 // /filtered: attribute creation order index (type 9)
	bt2CorderPlainIdx       = 55760 // /plain: chunk index (type 10)
	newgratLinkNameBt2      = 2020  // h5stat_newgrat.h5 /: link name index (type 5, depth 3)
	newgratAttrNameBt2      = 1086  // h5stat_newgrat.h5 /DATASET_NAME: attribute name index (type 8, depth 1)
	tsohmFile               = "tools/test/h5stat/testfiles/h5stat_tsohm.h5"
	tsohmIndexBt2           = 1125 // SOHM index (type 7)
	tsohmHeap               = 1163 // SOHM fractal heap
	bt2CorderNumLinks       = 300
	bt2CorderNumAttrs       = 50
	bt2CorderFilteredDim    = 40
