func openB2TestFile(t *testing.T, path string, opts ...Option) *File {
	t.Helper()
	if !filepath.IsAbs(path) {
		if strings.HasPrefix(path, "testdata/") {
			p, err := filepath.Abs(path)
			require.NoError(t, err)
			path = p
		} else {
			path = filepath.Join(repoRoot(t), path)
		}
	}
	f, err := Open(path, append([]Option{WithExternalLinks(false)}, opts...)...)
	require.NoError(t, err)
	t.Cleanup(func() { f.Close() })
	return f
}

// bt2RawClass is a record class that keeps the raw record bytes (for trees
// whose record class needs a context the test cannot build).
func bt2RawClass(id uint8) *h5b2Class {
	return &h5b2Class{
		id: id,
		decode: func(f *File, ctx any, p *image) (any, error) {
			return append([]byte(nil), p.rest()...), nil
		},
	}
}

// bt2TestClass picks the record class (and context) for a tree type, or the
// raw class for the chunk index and test types.
func bt2TestClass(f *File, typ uint8) (*h5b2Class, any) {
	switch typ {
	case h5b2FheapHugeIndirID, h5b2FheapHugeFiltIndirID, h5b2FheapHugeDirID, h5b2FheapHugeFiltDirID:
		return h5hfHugeBt2Class(typ), h5hfHugeBt2CrtContext(f)
	case h5b2GrpDenseNameID:
		return h5gBt2Name(), nil
	case h5b2GrpDenseCorderID:
		return h5gBt2Corder(), nil
	case h5b2SohmIndexID:
		return h5smIndex(), h5smBt2CrtContext(f)
	case h5b2AttrDenseNameID:
		return h5aBt2Name(), nil
	case h5b2AttrDenseCorderID:
		return h5aBt2Corder(), nil
	}
	return bt2RawClass(typ), nil
}

// bt2Records iterates bt and returns every record.
func bt2Records(t *testing.T, bt *h5b2) []any {
	t.Helper()
	var recs []any
	require.NoError(t, bt.iterate(func(rec any) error {
		recs = append(recs, rec)
		return nil
	}))
	return recs
}

// bt2At returns the record at idx via bt.indexOrder.
func bt2At(t *testing.T, bt *h5b2, dec bool, idx uint64) any {
	t.Helper()
	var got any
	require.NoError(t, bt.indexOrder(dec, idx, func(rec any) error {
		got = rec
		return nil
	}))
	return got
}

// scanBTHD returns the file offsets of every "BTHD" signature in path.
func scanBTHD(t *testing.T, path string) []int {
	b, err := os.ReadFile(path)
	require.NoError(t, err)
	var offs []int
	for i := 0; ; {
		j := bytes.Index(b[i:], []byte(h5b2HdrMagic))
		if j < 0 {
			return offs
		}
		offs = append(offs, i+j)
		i += j + 1
	}
}

// TestB2Corpus opens every v2 B-tree header found in the corpus (and the
// test files in testdata), iterates every record and checks the count
// against the header and the first/last records against H5B2_index.
func TestB2Corpus(t *testing.T) {
	files := corpusFiles(t)
	for _, name := range []string{"bt2_corder.h5", "fheap_huge.h5", "fheap_filtered.h5"} {
		p, err := filepath.Abs(filepath.Join("testdata", name))
		require.NoError(t, err)
		files = append(files, p)
	}
	trees := map[uint8]int{}
	for _, path := range files {
		offs := scanBTHD(t, path)
		if len(offs) == 0 {
			continue
		}
		f, err := Open(path, WithExternalLinks(false))
		if err != nil {
			t.Logf("%s: %v", path, err)
			continue
		}
		for _, off := range offs {
			addr := haddr(off) - f.baseAddr
			hdr, err := h5b2HdrProtect(f, addr)
			require.NoError(t, err, "%s: header at %d", path, addr)
			cls, ctx := bt2TestClass(f, hdr.typ)
			bt, err := f.b2Open(addr, cls, ctx)
			require.NoError(t, err, "%s: %d", path, addr)
			recs := bt2Records(t, bt)
			require.EqualValues(t, bt.numRecords(), len(recs), "%s: %d", path, addr)
			if len(recs) > 0 {
				assert.Equal(t, recs[0], bt2At(t, bt, false, 0))
				assert.Equal(t, recs[len(recs)-1], bt2At(t, bt, false, uint64(len(recs)-1)))
				assert.Equal(t, recs[0], bt2At(t, bt, true, uint64(len(recs)-1)))
			}
			trees[hdr.typ]++
		}
		f.Close()
	}
	t.Logf("v2 B-trees by type: %v", trees)
	for _, typ := range []uint8{1, 2, 5, 6, 7, 8, 9, 10, 11} {
		assert.NotZero(t, trees[typ], "no v2 B-tree of type %d", typ)
	}
}

// TestB2HeaderNodeInfo checks the derived node sizing of a depth-3 tree
// against h5debug ("Node Info: (max_nrec/split_nrec/merge_nrec)").
func TestB2HeaderNodeInfo(t *testing.T) {
	f := openB2TestFile(t, newgratFile)
	hdr, err := h5b2HdrProtect(f, newgratLinkNameBt2)
	require.NoError(t, err)
	assert.EqualValues(t, h5b2GrpDenseNameID, hdr.typ)
	assert.EqualValues(t, 512, hdr.nodeSize)
	assert.EqualValues(t, 11, hdr.rrecSize)
	assert.EqualValues(t, 3, hdr.depth)
	assert.EqualValues(t, 100, hdr.splitPercent)
	assert.EqualValues(t, 40, hdr.mergePercent)
	assert.Equal(t, haddr(3630911), hdr.rootAddr)
	assert.EqualValues(t, 1, hdr.rootNrec)
	assert.EqualValues(t, newgratNumLinks, hdr.rootAllNrec)
	assert.Equal(t, h5b2HeaderSize(8, 8), hdr.hdrSize)
	assert.EqualValues(t, 1, hdr.maxNrecSize)
	want := []h5b2NodeInfo{
		{maxNrec: 45, splitNrec: 45, mergeNrec: 18, cumMaxNrec: 45, cumMaxNrecSize: 0},
		{maxNrec: 24, splitNrec: 24, mergeNrec: 9, cumMaxNrec: 25*45 + 24, cumMaxNrecSize: 2},
		{maxNrec: 22, splitNrec: 22, mergeNrec: 8, cumMaxNrec: 23*1149 + 22, cumMaxNrecSize: 2},
		{maxNrec: 22, splitNrec: 22, mergeNrec: 8, cumMaxNrec: 23*26449 + 22, cumMaxNrecSize: 3},
	}
	assert.Equal(t, want, hdr.nodeInfo)

	// h5debug ... 1125: SOHM index, (29/29/11).
	f2 := openB2TestFile(t, tsohmFile)
	hdr2, err := h5b2HdrProtect(f2, tsohmIndexBt2)
	require.NoError(t, err)
	assert.EqualValues(t, h5b2SohmIndexID, hdr2.typ)
	assert.EqualValues(t, 17, hdr2.rrecSize)
	assert.Equal(t, []h5b2NodeInfo{{maxNrec: 29, splitNrec: 29, mergeNrec: 11, cumMaxNrec: 29}}, hdr2.nodeInfo)

	// The class must match the header's type.
	_, err = f.b2Open(newgratLinkNameBt2, h5gBt2Corder(), nil)
	assert.Error(t, err)
}

// testLinkDecoder decodes a dense link heap object with the test parser
// (stands in for the link message decoder).
func testLinkDecoder(f *File, obj []byte) (*h5oLink, error) {
	l, err := parseLink(obj, int(f.sizeofAddr))
	if err != nil {
		return nil, err
	}
	return &h5oLink{name: l.name, softName: l.value}, nil
}

// TestB2DenseLinkNames looks up dense links by name (H5G__dense_lookup:
// hash, then the full name from the fractal heap) in a depth-1 and a
// depth-3 name index.
func TestB2DenseLinkNames(t *testing.T) {
	f := openB2TestFile(t, bt2CorderFile)
	fh, err := f.hfOpen(bt2CorderLinksHeap)
	require.NoError(t, err)
	bt, err := f.b2Open(bt2CorderLinksName, h5gBt2Name(), nil)
	require.NoError(t, err)
	assert.EqualValues(t, 1, bt.hdr.depth)

	recs := bt2Records(t, bt)
	require.Len(t, recs, bt2CorderNumLinks)
	names := map[string]bool{}
	var prev uint32
	for i, r := range recs {
		rec := r.(*h5gDenseBt2NameRec)
		assert.GreaterOrEqual(t, rec.hash, prev, "records are in hash order")
		prev = rec.hash
		obj, err := fh.read(rec.id[:])
		require.NoError(t, err)
		lnk, err := testLinkDecoder(f, obj)
		require.NoError(t, err)
		assert.Equal(t, checksumLookup3([]byte(lnk.name), 0), rec.hash, lnk.name)
		names[lnk.name] = true
		assert.Same(t, r, bt2At(t, bt, false, uint64(i)))
	}
	assert.Len(t, names, bt2CorderNumLinks)

	for i := 0; i < bt2CorderNumLinks; i++ {
		name := fmt.Sprintf("l%04d", i)
		var got *h5oLink
		ud := &h5gBt2UdCommon{
			fheap:      fh,
			name:       name,
			nameHash:   checksumLookup3([]byte(name), 0),
			decodeLink: testLinkDecoder,
			foundOp:    func(lnk *h5oLink) error { got = lnk; return nil },
		}
		found, err := bt.find(ud, nil)
		require.NoError(t, err)
		require.True(t, found, name)
		require.NotNil(t, got, name)
		assert.Equal(t, name, got.name)
		assert.Equal(t, fmt.Sprintf("/t%04d", i), got.softName)
	}
	for _, name := range []string{"l0300", "", "missing", "l00000"} {
		ud := &h5gBt2UdCommon{fheap: fh, name: name, nameHash: checksumLookup3([]byte(name), 0), decodeLink: testLinkDecoder}
		found, err := bt.find(ud, nil)
		require.NoError(t, err)
		assert.False(t, found, name)
	}

	// A failing found callback is reported.
	ud := &h5gBt2UdCommon{fheap: fh, name: "l0007", nameHash: checksumLookup3([]byte("l0007"), 0), decodeLink: testLinkDecoder,
		foundOp: func(*h5oLink) error { return errors.New("boom") }}
	_, err = bt.find(ud, nil)
	assert.Error(t, err)

	// Depth-3 index of h5stat_newgrat.h5: 35001 links in a 4-level tree.
	g := openB2TestFile(t, newgratFile)
	gfh, err := g.hfOpen(1874)
	require.NoError(t, err)
	gbt, err := g.b2Open(newgratLinkNameBt2, h5gBt2Name(), nil)
	require.NoError(t, err)
	grecs := bt2Records(t, gbt)
	require.Len(t, grecs, newgratNumLinks)
	prev = 0
	for _, r := range grecs {
		rec := r.(*h5gDenseBt2NameRec)
		require.GreaterOrEqual(t, rec.hash, prev)
		prev = rec.hash
	}
	rng := rand.New(rand.NewSource(1))
	idxs := []uint64{0, 1, 44, 45, 46, 1148, 1149, 1150, 26449, 26450, newgratNumLinks - 1}
	for i := 0; i < 300; i++ {
		idxs = append(idxs, uint64(rng.Intn(newgratNumLinks)))
	}
	for _, i := range idxs {
		assert.Same(t, grecs[i], bt2At(t, gbt, false, i), "index %d", i)
		assert.Same(t, grecs[newgratNumLinks-1-i], bt2At(t, gbt, true, i), "reverse index %d", i)
	}
	assert.Error(t, gbt.index(newgratNumLinks, func(any) error { return nil }))

	for _, i := range idxs[:60] {
		rec := grecs[i].(*h5gDenseBt2NameRec)
		obj, err := gfh.read(rec.id[:])
		require.NoError(t, err)
		lnk, err := testLinkDecoder(g, obj)
		require.NoError(t, err)
		var got *h5oLink
		ud := &h5gBt2UdCommon{fheap: gfh, name: lnk.name, nameHash: rec.hash, decodeLink: testLinkDecoder,
			foundOp: func(l *h5oLink) error { got = l; return nil }}
		var foundRec any
		found, err := gbt.find(ud, func(r any) error { foundRec = r; return nil })
		require.NoError(t, err)
		require.True(t, found, lnk.name)
		assert.Equal(t, lnk.name, got.name)
		assert.Equal(t, rec.id, foundRec.(*h5gDenseBt2NameRec).id)
	}

	// Early stop.
	n := 0
	require.NoError(t, gbt.iterate(func(any) error {
		n++
		if n == 1000 {
			return errBIterStop
		}
		return nil
	}))
	assert.Equal(t, 1000, n)
	stopErr := errors.New("stop here")
	err = gbt.iterate(func(any) error { return stopErr })
	assert.ErrorIs(t, err, stopErr)
}

// TestB2DenseLinkCorder walks the creation order index of /links (type 6)
// by index, find and neighbor.
func TestB2DenseLinkCorder(t *testing.T) {
	f := openB2TestFile(t, bt2CorderFile)
	fh, err := f.hfOpen(bt2CorderLinksHeap)
	require.NoError(t, err)
	bt, err := f.b2Open(bt2CorderLinksCorder, h5gBt2Corder(), nil)
	require.NoError(t, err)
	assert.EqualValues(t, 1, bt.hdr.depth)
	assert.EqualValues(t, bt2CorderNumLinks, bt.numRecords())

	recs := bt2Records(t, bt)
	require.Len(t, recs, bt2CorderNumLinks)
	for i, r := range recs {
		rec := r.(*h5gDenseBt2CorderRec)
		assert.EqualValues(t, i, rec.corder)
		assert.Same(t, r, bt2At(t, bt, false, uint64(i)))
		assert.Same(t, r, bt2At(t, bt, true, uint64(bt2CorderNumLinks-1-i)))

		var found *h5gDenseBt2CorderRec
		ok, err := bt.find(&h5gBt2UdCommon{corder: int64(i)}, func(r any) error { found = r.(*h5gDenseBt2CorderRec); return nil })
		require.NoError(t, err)
		require.True(t, ok)
		assert.Same(t, rec, found)

		obj, err := fh.read(rec.id[:])
		require.NoError(t, err)
		lnk, err := testLinkDecoder(f, obj)
		require.NoError(t, err)
		assert.Equal(t, fmt.Sprintf("l%04d", i), lnk.name)
	}
	ok, err := bt.find(&h5gBt2UdCommon{corder: bt2CorderNumLinks}, nil)
	require.NoError(t, err)
	assert.False(t, ok)
	ok, err = bt.find(&h5gBt2UdCommon{corder: -1}, nil)
	require.NoError(t, err)
	assert.False(t, ok)

	// H5B2_neighbor.
	for _, c := range []int64{1, 32, 33, 100, 150, 299} {
		var got int64 = -100
		require.NoError(t, bt.neighbor(h5b2CompareLess, &h5gBt2UdCommon{corder: c}, func(r any) error {
			got = r.(*h5gDenseBt2CorderRec).corder
			return nil
		}))
		assert.Equal(t, c-1, got, "less than %d", c)
	}
	for _, c := range []int64{0, 31, 32, 100, 298, -5} {
		var got int64 = -100
		require.NoError(t, bt.neighbor(h5b2CompareGreater, &h5gBt2UdCommon{corder: c}, func(r any) error {
			got = r.(*h5gDenseBt2CorderRec).corder
			return nil
		}))
		want := c + 1
		if c < 0 {
			want = 0
		}
		assert.Equal(t, want, got, "greater than %d", c)
	}
	assert.Error(t, bt.neighbor(h5b2CompareLess, &h5gBt2UdCommon{corder: 0}, func(any) error { return nil }))
	assert.Error(t, bt.neighbor(h5b2CompareGreater, &h5gBt2UdCommon{corder: 299}, func(any) error { return nil }))
}

// testAttrDecoder decodes a dense attribute heap object with the test
// parser (stands in for the attribute message decoder).
func testAttrDecoder(f *File, obj []byte) (*h5oAttr, error) {
	a, err := parseAttr(obj, int(f.sizeofSize))
	if err != nil {
		return nil, err
	}
	return &h5oAttr{name: a.name, data: a.data}, nil
}

// TestB2DenseAttributes looks up dense attributes by name and creation
// order (types 8 and 9).
func TestB2DenseAttributes(t *testing.T) {
	f := openB2TestFile(t, bt2CorderFile)
	fh, err := f.hfOpen(bt2CorderAttrHeap)
	require.NoError(t, err)
	byName, err := f.b2Open(bt2CorderAttrName, h5aBt2Name(), nil)
	require.NoError(t, err)
	byCorder, err := f.b2Open(bt2CorderAttrCorder, h5aBt2Corder(), nil)
	require.NoError(t, err)

	crecs := bt2Records(t, byCorder)
	require.Len(t, crecs, bt2CorderNumAttrs)
	for i, r := range crecs {
		rec := r.(*h5aDenseBt2CorderRec)
		assert.EqualValues(t, i, rec.corder)
		assert.Zero(t, rec.flags)
		obj, err := fh.read(rec.id[:])
		require.NoError(t, err)
		attr, err := testAttrDecoder(f, obj)
		require.NoError(t, err)
		assert.Equal(t, fmt.Sprintf("attr%02d", i), attr.name)
		assert.Equal(t, binary.LittleEndian.AppendUint32(nil, uint32(i)), attr.data)

		var found any
		ok, err := byCorder.find(&h5aBt2UdCommon{corder: uint32(i)}, func(r any) error { found = r; return nil })
		require.NoError(t, err)
		require.True(t, ok)
		assert.Same(t, r, found)
	}

	nrecs := bt2Records(t, byName)
	require.Len(t, nrecs, bt2CorderNumAttrs)
	for i := 0; i < bt2CorderNumAttrs; i++ {
		name := fmt.Sprintf("attr%02d", i)
		var got *h5oAttr
		ud := &h5aBt2UdCommon{fheap: fh, name: name, nameHash: checksumLookup3([]byte(name), 0), decodeAttr: testAttrDecoder,
			foundOp: func(a *h5oAttr) error { got = a; return nil }}
		var rec *h5aDenseBt2NameRec
		ok, err := byName.find(ud, func(r any) error { rec = r.(*h5aDenseBt2NameRec); return nil })
		require.NoError(t, err)
		require.True(t, ok, name)
		assert.Equal(t, name, got.name)
		assert.EqualValues(t, i, got.crtIdx)
		assert.Nil(t, got.shared)
		assert.EqualValues(t, i, rec.corder)
		assert.Equal(t, binary.LittleEndian.AppendUint32(nil, uint32(i)), got.data)
	}
	ud := &h5aBt2UdCommon{fheap: fh, name: "attr50", nameHash: checksumLookup3([]byte("attr50"), 0), decodeAttr: testAttrDecoder}
	ok, err := byName.find(ud, nil)
	require.NoError(t, err)
	assert.False(t, ok)

	// h5stat_newgrat.h5: /DATASET_NAME's 100 attributes in a depth-1 tree;
	// the records match the heap IDs and hashes printed by h5debug.
	g := openB2TestFile(t, newgratFile)
	gfh, err := g.hfOpen(6304375)
	require.NoError(t, err)
	gbt, err := g.b2Open(newgratAttrNameBt2, h5aBt2Name(), nil)
	require.NoError(t, err)
	assert.EqualValues(t, 1, gbt.hdr.depth)
	grecs := bt2Records(t, gbt)
	require.Len(t, grecs, newgratNumAttrs)
	byID := map[uint64]*h5aDenseBt2NameRec{}
	for _, r := range grecs {
		rec := r.(*h5aDenseBt2NameRec)
		byID[binary.LittleEndian.Uint64(rec.id[:])] = rec
	}
	for _, want := range newgratAttrRecords {
		rec := byID[want.id]
		require.NotNil(t, rec, "%#x", want.id)
		assert.Equal(t, want.hash, rec.hash)
		obj, err := gfh.read(rec.id[:])
		require.NoError(t, err)
		attr, err := testAttrDecoder(g, obj)
		require.NoError(t, err)
		ok, err := gbt.find(&h5aBt2UdCommon{fheap: gfh, name: attr.name, nameHash: rec.hash, decodeAttr: testAttrDecoder}, nil)
		require.NoError(t, err)
		assert.True(t, ok, attr.name)
	}
}

// testLayout builds the parts of a layout message h5dBt2IdxOpen needs.
func testLayout(idxAddr haddr, dims ...uint64) *h5oLayout {
	return &h5oLayout{
		typ:          h5dChunked,
		version:      4,
		chunkNdims:   uint32(len(dims)),
		chunkDim:     dims,
		chunkIdxType: h5dChunkIdxBt2,
		chunkIdxAddr: idxAddr,
	}
}

// TestB2ChunkIndex reads the chunk records of the v2 B-tree indexed
// datasets in bt2_corder.h5 (types 10 and 11) and checks them against the
// raw data (h5dump: value i*ncols+j).
func TestB2ChunkIndex(t *testing.T) {
	f := openB2TestFile(t, bt2CorderFile)

	// /plain: 30x30 int32, 1x1 chunks, unfiltered.
	bt, ctx, err := h5dBt2IdxOpen(f, testLayout(bt2CorderPlainIdx, 1, 1, 4))
	require.NoError(t, err)
	assert.EqualValues(t, h5b2CdsetID, bt.hdr.typ)
	assert.EqualValues(t, 2, ctx.ndims)
	assert.EqualValues(t, 4, ctx.chunkSize)
	assert.Equal(t, 2, ctx.chunkSizeLen) // 1 + (log2(4)+8)/8
	assert.EqualValues(t, 1, bt.hdr.depth)
	recs := bt2Records(t, bt)
	require.Len(t, recs, bt2CorderPlainDim*bt2CorderPlainDim)
	for k, r := range recs {
		rec := r.(*h5dChunkRec)
		i, j := uint64(k/bt2CorderPlainDim), uint64(k%bt2CorderPlainDim)
		assert.Equal(t, []uint64{i, j}, rec.scaled, "records in scaled order")
		assert.EqualValues(t, 4, rec.nbytes)
		assert.Zero(t, rec.filterMask)
		buf, err := f.readAt(rec.chunkAddr, 4)
		require.NoError(t, err)
		assert.EqualValues(t, k, binary.LittleEndian.Uint32(buf))

		var found *h5dChunkRec
		ok, err := bt.find(&h5dBt2Ud{rec: h5dChunkRec{scaled: []uint64{i, j}}, ndims: ctx.ndims}, func(r any) error {
			found = r.(*h5dChunkRec)
			return nil
		})
		require.NoError(t, err)
		require.True(t, ok)
		assert.Same(t, rec, found)
	}
	ok, err := bt.find(&h5dBt2Ud{rec: h5dChunkRec{scaled: []uint64{30, 0}}, ndims: 2}, nil)
	require.NoError(t, err)
	assert.False(t, ok)

	// /filtered: 40x40 int32, 1x2 chunks, deflate.
	bt, ctx, err = h5dBt2IdxOpen(f, testLayout(bt2CorderFilteredIdx, 1, 2, 4))
	require.NoError(t, err)
	assert.EqualValues(t, h5b2CdsetFiltID, bt.hdr.typ)
	assert.EqualValues(t, 8, ctx.chunkSize)
	assert.Equal(t, 2, ctx.chunkSizeLen) // 1 + (log2(8)+8)/8
	assert.EqualValues(t, 8+2+4+2*8, bt.hdr.rrecSize)
	recs = bt2Records(t, bt)
	require.Len(t, recs, bt2CorderFilteredChunks)
	for k, r := range recs {
		rec := r.(*h5dChunkRec)
		i, j := uint64(k/20), uint64(k%20)
		assert.Equal(t, []uint64{i, j}, rec.scaled)
		assert.Zero(t, rec.filterMask)
		raw, err := f.readAt(rec.chunkAddr, int(rec.nbytes))
		require.NoError(t, err)
		zr, err := zlib.NewReader(bytes.NewReader(raw))
		require.NoError(t, err)
		data, err := io.ReadAll(zr)
		require.NoError(t, err)
		v := uint32(i*bt2CorderFilteredDim + 2*j)
		assert.Equal(t, binary.LittleEndian.AppendUint32(binary.LittleEndian.AppendUint32(nil, v), v+1), data)
	}
	for _, k := range []uint64{0, 1, 77, 799} {
		rec := bt2At(t, bt, false, k).(*h5dChunkRec)
		assert.Equal(t, []uint64{k / 20, k % 20}, rec.scaled)
	}

	// Wrong index type / dimensionality.
	_, _, err = h5dBt2IdxOpen(f, &h5oLayout{chunkIdxType: h5dChunkIdxEarray, chunkIdxAddr: bt2CorderPlainIdx})
	assert.Error(t, err)
	_, _, err = h5dBt2IdxOpen(f, testLayout(bt2CorderPlainIdx, 4))
	assert.Error(t, err)
	_, _, err = h5dBt2IdxOpen(f, testLayout(bt2CorderLinksName, 1, 1, 4))
	assert.Error(t, err)

	// The chunk index of h5format_convert's test file (type 10, 3 dims).
	g := openB2TestFile(t, "tools/test/h5format_convert/testfiles/h5fc_ext_none.h5")
	hdr, err := h5b2HdrProtect(g, 1885)
	require.NoError(t, err)
	assert.EqualValues(t, h5b2CdsetID, hdr.typ)
	assert.EqualValues(t, 24, hdr.rrecSize) // address + 2 scaled offsets
}

// TestB2SharedMessageIndex reads the SOHM index of h5stat_tsohm.h5 (type
// 7): one dataspace message shared by the three datasets.
func TestB2SharedMessageIndex(t *testing.T) {
	f := openB2TestFile(t, tsohmFile)
	fh, err := f.hfOpen(tsohmHeap)
	require.NoError(t, err)
	bt, err := f.b2Open(tsohmIndexBt2, h5smIndex(), h5smBt2CrtContext(f))
	require.NoError(t, err)
	recs := bt2Records(t, bt)
	require.Len(t, recs, 1)
	rec := recs[0].(*h5smSohm)
	assert.Equal(t, h5smInHeap, rec.location)
	assert.EqualValues(t, 0x71c9b1d8, rec.hash)
	assert.EqualValues(t, 3, rec.heapLoc.refCount) // dataset, dataset2, dataset3

	obj, err := fh.read(rec.heapLoc.fheapID[:])
	require.NoError(t, err)
	// The hash is H5_checksum_lookup3(encoding, size, type_id) of the
	// dataspace message.
	assert.Equal(t, rec.hash, checksumLookup3(obj, h5oSdspaceID))

	// Look the message up by its encoding (H5SM__message_compare through the
	// heap) and by its heap ID.
	key := &h5smMesgKey{file: f, fheap: fh, encoding: obj, message: h5smSohm{location: h5smInOh, hash: rec.hash}}
	var found *h5smSohm
	ok, err := bt.find(key, func(r any) error { found = r.(*h5smSohm); return nil })
	require.NoError(t, err)
	require.True(t, ok)
	assert.Same(t, rec, found)
	ok, err = bt.find(&h5smMesgKey{message: h5smSohm{location: h5smInHeap, heapLoc: h5smHeapLoc{fheapID: rec.heapLoc.fheapID}}}, nil)
	require.NoError(t, err)
	assert.True(t, ok)
	other := append([]byte(nil), obj...)
	other[len(other)-1] ^= 1
	ok, err = bt.find(&h5smMesgKey{file: f, fheap: fh, encoding: other, message: h5smSohm{location: h5smInOh, hash: rec.hash}}, nil)
	require.NoError(t, err)
	assert.False(t, ok)
	ok, err = bt.find(&h5smMesgKey{message: h5smSohm{location: h5smInOh, hash: rec.hash + 1}}, nil)
	require.NoError(t, err)
	assert.False(t, ok)

	// Records stored in an object header.
	ctx := h5smBt2CrtContext(f)
	raw := []byte{1, 0x78, 0x56, 0x34, 0x12, 0, 3, 7, 0}
	raw = binary.LittleEndian.AppendUint64(raw, 0x1234)
	m, err := h5smMessageDecode(f.newImage(raw), ctx)
	require.NoError(t, err)
	assert.Equal(t, &h5smSohm{location: h5smInOh, hash: 0x12345678, msgTypeID: 3, mesgLoc: h5oMesgLoc{index: 7, ohAddr: 0x1234}}, m)
	_, err = h5smMessageDecode(f.newImage([]byte{2, 0, 0, 0, 0}), ctx)
	assert.Error(t, err)
	_, err = h5smMessageDecode(f.newImage(raw[:10]), ctx)
	assert.Error(t, err)
}

// TestB2Corrupt damages the B-tree metadata of bt2_corder.h5 and checks that
// opening and walking the trees fails cleanly (no panics).
func TestB2Corrupt(t *testing.T) {
	path, err := filepath.Abs(bt2CorderFile)
	require.NoError(t, err)
	orig, err := os.ReadFile(path)
	require.NoError(t, err)
	type tree struct {
		addr haddr
		cls  func() *h5b2Class
	}
	trees := []tree{
		{bt2CorderLinksName, h5gBt2Name},
		{bt2CorderLinksCorder, h5gBt2Corder},
		{bt2CorderAttrName, h5aBt2Name},
		{bt2CorderAttrCorder, h5aBt2Corder},
		{bt2CorderPlainIdx, func() *h5b2Class { return bt2RawClass(h5b2CdsetID) }},
		{bt2CorderFilteredIdx, func() *h5b2Class { return bt2RawClass(h5b2CdsetFiltID) }},
	}
	walk := func(b []byte, verify bool) error {
		f, err := OpenReader(bytes.NewReader(b), int64(len(b)), WithChecksumVerification(verify))
		if err != nil {
			return err
		}
		defer f.Close()
		var first error
		for _, tr := range trees {
			bt, err := f.b2Open(tr.addr, tr.cls(), nil)
			if err == nil {
				n := uint64(0)
				err = bt.iterate(func(any) error { n++; return nil })
				if err == nil && n != bt.numRecords() {
					err = fmt.Errorf("count %d != %d", n, bt.numRecords())
				}
				if err == nil && n > 0 {
					err = bt.index(n-1, func(any) error { return nil })
				}
			}
			if err != nil && first == nil {
				first = err
			}
		}
		return first
	}
	require.NoError(t, walk(orig, true))

	// Checksum mismatches in a header, a leaf and an internal node.
	for _, off := range []int{bt2CorderLinksName + 10, bt2CorderPlainIdx + 20} {
		b := append([]byte(nil), orig...)
		b[off] ^= 0x40
		err := walk(b, true)
		assert.ErrorIs(t, err, ErrBadChecksum, "offset %d", off)
	}
	b := append([]byte(nil), orig...)
	b[57846+8] ^= 0x01 // record in the root internal node of /plain's index
	assert.ErrorIs(t, walk(b, true), ErrBadChecksum)

	// Random damage to the B-tree nodes with checksums off: errors or wrong
	// counts are fine, panics are not.
	var nodes []int
	for i := 0; i+4 <= len(orig); i++ {
		switch string(orig[i : i+4]) {
		case h5b2HdrMagic, h5b2IntMagic, h5b2LeafMagic:
			nodes = append(nodes, i)
		}
	}
	require.NotEmpty(t, nodes)
	rng := rand.New(rand.NewSource(2))
	for iter := 0; iter < 400; iter++ {
		b := append([]byte(nil), orig...)
		for k := 0; k < 1+rng.Intn(4); k++ {
			off := nodes[rng.Intn(len(nodes))] + rng.Intn(64)
			if off < len(b) {
				b[off] = byte(rng.Intn(256))
			}
		}
		_ = walk(b, false)
	}

	// Hand-made headers: zero sizes, bad version/type, huge depth.
	hdrAt := bt2CorderLinksName
	for _, mut := range []func(b []byte){
		func(b []byte) { b[hdrAt+4] = 1 },                                             // version
		func(b []byte) { b[hdrAt+5] = h5b2NumBtreeID },                                // type
		func(b []byte) { binary.LittleEndian.PutUint32(b[hdrAt+6:], 0) },              // node size
		func(b []byte) { binary.LittleEndian.PutUint32(b[hdrAt+6:], 12) },             // node size < prefix + record
		func(b []byte) { binary.LittleEndian.PutUint16(b[hdrAt+10:], 0) },             // record size
		func(b []byte) { binary.LittleEndian.PutUint32(b[hdrAt+6:], 1<<20) },          // too many records per leaf
		func(b []byte) { binary.LittleEndian.PutUint16(b[hdrAt+12:], 0xffff) },        // depth
		func(b []byte) { binary.LittleEndian.PutUint16(b[hdrAt+12:], 40) },            // depth
		func(b []byte) { binary.LittleEndian.PutUint16(b[hdrAt+24:], 0xffff) },        // root nrec
		func(b []byte) { binary.LittleEndian.PutUint64(b[hdrAt+16:], 1<<40) },         // root address
		func(b []byte) { binary.LittleEndian.PutUint64(b[hdrAt+26:], 1<<62) },         // all nrec
		func(b []byte) { binary.LittleEndian.PutUint64(b[hdrAt+16:], uint64(hdrAt)) }, // root = header
		func(b []byte) { binary.LittleEndian.PutUint64(b[hdrAt+16:], 1598) },          // root = other tree's root
		func(b []byte) { copy(b[hdrAt:], "BTHX") },                                    // signature
		func(b []byte) { binary.LittleEndian.PutUint32(b[hdrAt+6:], 0xffffffff) },     // node size past EOF
	} {
		b := append([]byte(nil), orig...)
		mut(b)
		f, err := OpenReader(bytes.NewReader(b), int64(len(b)), WithChecksumVerification(false))
		require.NoError(t, err)
		bt, err := f.b2Open(haddr(hdrAt), h5gBt2Name(), nil)
		if err == nil {
			_ = bt.iterate(func(any) error { return nil })
			_ = bt.index(bt.numRecords()-1, func(any) error { return nil })
			_, _ = bt.find(&h5gBt2UdCommon{nameHash: 1}, nil)
		}
		f.Close()
	}
}
